sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 */

function applySAMFilter ({ api, event, imports }) {
	if(event.elementId === "filter_1") {
		if(event.payload.appliedFilters[0].values && event.payload.appliedFilters[0].values[0] === "published"){
			api.setState("publishedStatusFilter", "publishedStatus=published");
		} else if (event.payload.appliedFilters[0].values && event.payload.appliedFilters[0].values[0] === "unpublished"){
			api.setState("publishedStatusFilter", "publishedStatus=unpublished");
		} else{
			api.setState("publishedStatusFilter", "");
		}
	}
	api.setState('parFilters', ({ currentValue }) => {
		const { payload: { appliedFilters } } = event;
		return imports['global.mergePARFilters']()(currentValue, appliedFilters);
	});
}
